def unique_jobs(rows):
    # Track first occurrence of each (source, source_id) pair
    seen = {}
    result = []
    for row in rows:
        source = row.get('source', '')
        source_id = row.get('source_id', '')
        key = (source, source_id)

        # Only add if this (source, source_id) pair hasn't been seen before
        if key not in seen:
            seen[key] = True
            result.append(row)

    return result
